<template>
  <template v-if="selectedCustomer">
  <button class="back" @click="view = 'customers'">← 返回客戶</button>
  <section class="holder-card guilloche-panel"><div class="holder-main"><span class="holder-kicker">{{ selectedCustomer.is_self ? '本公司自有' : '委託人' }}</span><h1>{{ selectedCustomer.name }}</h1><p>{{ selectedCustomer.kind }} · <span class="num">{{ selectedCustomer.phone || '未填電話' }}</span></p></div><dl class="holder-counts"><div><dt>牌照</dt><dd class="num">{{ customerPlates.length }}</dd></div><div><dt>公司組</dt><dd class="num">{{ companyGroups.length }}</dd></div><div><dt>車輛</dt><dd class="num">{{ customerVehicles.length }}</dd></div><div><dt>工單</dt><dd class="num">{{ customerRequests.length }}</dd></div></dl><div class="holder-actions"><button v-if="!selectedCustomer.is_self" class="button outline on-dark" @click="modal = 'customer-user'">開通登入</button><select class="button on-dark" aria-label="新增資料" @change="addRecord($event)"><option value="">＋ 新增</option><option value="plate">牌照</option><option value="vehicle">車輛</option><option value="company">公司組</option><option value="request">工單</option></select></div></section>
  <Segmented v-model="customerTab" :options="tabs" label="客戶資料分頁" />
  <template v-if="customerTab === 'overview'"><div class="stat-row"><StatCard label="已逾期" tone="danger" :value="customerDeadlines.filter(item => item.level === 'overdue').length" hint="立即跟進" /><StatCard label="需處理" tone="warning" :value="customerDeadlines.filter(item => item.level === 'due').length" hint="提醒期內" /><StatCard label="待錄入" tone="neutral" :value="customerDeadlines.filter(item => item.level === 'missing').length" hint="補上日期或資料" /><StatCard label="進行中工單" tone="info" :value="customerRequests.filter(item => item.status !== '已完成').length" hint="未完成" /></div><div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>需要處理的事</h2><p>只顯示此客戶的逾期、需處理與待錄入。</p></div></div><div v-for="item in customerDeadlines" :key="`${item.ruleCode}:${item.ownerId}`" class="record-row"><div><strong>{{ item.name }}</strong><small>{{ item.ownerLabel }}<template v-if="item.handler === 'client'"> · 客戶自理</template></small></div><DueDate :date="item.dueOn" /></div><div v-if="!customerDeadlines.length" class="empty">目前沒有待處理項目</div></section><section class="panel"><div class="panel-head"><div><h2>進行中工單</h2><p>此客戶尚未完成的工單。</p></div></div><button v-for="request in customerRequests.filter(item => item.status !== '已完成')" :key="request.id" class="list-row" @click="openRequest(request)"><span class="list-icon">{{ iconFor(request.service_code) }}</span><span class="list-main"><strong>{{ request.title }}</strong><small>{{ request.stage }} · {{ request.status }}</small></span><span>→</span></button><div v-if="!customerRequests.some(item => item.status !== '已完成')" class="empty">目前沒有進行中工單</div></section></div></template>
  <template v-else-if="customerTab === 'companies'"><Companies :initial-customer="selectedCustomer.id" :add-group-request="addGroupRequest" @plate="openPlateById" @saved="companySaved" @error="showError" /></template>
  <template v-else-if="customerTab === 'plates'"><section class="panel table-panel"><div class="panel-head"><div><h2>客戶牌照</h2><p>欄位與牌照總表一致。</p></div></div><DataTable :columns="plateColumns" :data="customerPlates" :min-width="880"><template #cell-mainland_plate="{ row }"><button class="phase-link" @click="openPlate(row)"><PlateChip :plate="row.mainland_plate" /> · <PlateChip :plate="row.local_plate" :route="row.route" /></button></template><template #cell-holder_company="{ row }">{{ row.holder_company || row.card_data?.company || '持牌公司待補充' }}</template><template #cell-customer_id>{{ selectedCustomer.name }}</template><template #cell-port="{ row }">{{ row.port || '待設定' }}</template><template #cell-card_expires_on="{ row }"><DueDate :date="row.card_expires_on" /></template><template #cell-permit_expires_on="{ row }"><DueDate :date="row.permit_expires_on" editable label="CRP／通行證到期" :on-save="value => savePermit(row, value)" /></template><template #cell-health_status="{ row }"><span class="badge" :class="tone(row.health_status)">{{ label(row.health_status) }}</span></template></DataTable></section></template>
  <template v-else-if="customerTab === 'vehicles'"><section class="panel"><div class="panel-head"><div><h2>車輛與司機</h2><p>司機名單取自各牌照批文卡上的駕駛人。</p></div></div><div v-for="vehicle in customerVehicles" :key="vehicle.id" class="record-row"><button class="phase-link" @click="openVehicle(vehicle)"><PlateChip :plate="vehicle.plate" :route="vehicle.route" /></button><span>{{ vehicle.route }} · {{ vehicle.origin }} · {{ vehicle.type }}</span><span>{{ driversFor(vehicle).join('、') || '批文卡尚未填寫駕駛人' }}</span></div><div v-if="!customerVehicles.length" class="empty">尚未登記車輛</div></section></template>
  <template v-else><section class="panel"><div class="panel-head"><div><h2>客戶業務</h2><p>沿用現有工單詳情與節點操作。</p></div></div><button v-for="request in customerRequests" :key="request.id" class="list-row" @click="openRequest(request)"><span class="list-icon">{{ iconFor(request.service_code) }}</span><span class="list-main"><strong>{{ request.title }}</strong><small>{{ request.stage }}</small></span><span class="badge">{{ request.status }}</span></button><div v-if="!customerRequests.length" class="empty">尚無工單</div></section></template>
  </template>
  <div v-else class="panel empty" role="status">正在載入客戶資料…</div>
</template>
<script setup>
import { computed, ref } from 'vue'
import Segmented from '../components/ui/Segmented.vue'
import PlateChip from '../components/ui/PlateChip.vue'
import DueDate from '../components/ui/DueDate.vue'
import StatCard from '../components/ui/StatCard.vue'
import DataTable from '../components/ui/DataTable.vue'
import Companies from './Companies.vue'
import { useAdminStore } from '../store'
const { view, selectedCustomer, modal, customerTab, customerPlates, customerVehicles, customerRequests, overviewData, companyGroups: allGroups, companyRecords, newRequest, saveTrackedItem, refresh, openPlate, openPlateById, openVehicle, openRequest, iconFor, showSuccess, showError } = useAdminStore()
const tabs = [{ value: 'overview', label: '概覽' }, { value: 'companies', label: '公司組' }, { value: 'plates', label: '牌照' }, { value: 'vehicles', label: '車輛與司機' }, { value: 'business', label: '業務' }]
const plateColumns = [{ key: 'mainland_plate', title: '車牌' }, { key: 'holder_company', title: '持牌公司' }, { key: 'customer_id', title: '客戶' }, { key: 'port', title: '口岸' }, { key: 'card_expires_on', title: '批文到期' }, { key: 'permit_expires_on', title: 'CRP／通行證到期' }, { key: 'usage_status', title: '使用' }, { key: 'health_status', title: '狀態' }]
const addGroupRequest = ref(0)
const companyGroups = computed(() => allGroups.value.filter(group => group.customer_id === selectedCustomer.value?.id))
const customerCompanies = computed(() => companyRecords.value.filter(company => company.customer_id === selectedCustomer.value?.id))
function addRecord(event) { const choice = event.target.value; event.target.value = ''; if (choice === 'company') { customerTab.value = 'companies'; addGroupRequest.value += 1 } else if (choice === 'request') { newRequest.value.customerId = selectedCustomer.value.id; view.value = 'new-request' } else if (choice) { useAdminStore().form.value = { customerId: selectedCustomer.value.id, route: '粵港', origin: '香港', kind: '個人' }; modal.value = choice } }
async function companySaved(message) { await refresh(); showSuccess(message) }
async function savePermit(plate, expiresOn) { return saveTrackedItem({ ownerType: 'plate', ownerId: plate.id, code: plate.route === '粵港' ? 'hk_crp' : 'mo_permit', expiresOn }) }
const customerDeadlines = computed(() => (overviewData.value.deadlines || []).filter(item => item.customerId === selectedCustomer.value?.id && ['overdue', 'due', 'missing'].includes(item.level)))
const tone = level => ({ overdue: 'danger', due: 'amber', missing: 'muted' }[level] || '')
const label = level => ({ overdue: '已逾期', due: '需處理', missing: '待錄入', ok: '正常' }[level] || level)
const driversFor = vehicle => [...new Set(customerPlates.value.filter(plate => plate.vehicle_id === vehicle.id).flatMap(plate => Object.entries(plate.card_data || {}).filter(([key, value]) => /^driver\d+$/.test(key) && value).map(([, value]) => value)))]
</script>
